import{_ as e}from"./chunks/tariff-pricing.Bu-VQfIy.js";import{_ as r,o as i,c as t,a2 as l}from"./chunks/framework.BjkiRu3Q.js";const u=JSON.parse('{"title":"Έλεγχος τιμολόγησης","description":"","frontmatter":{},"headers":[],"relativePath":"el/plus/pricing.md","filePath":"el/plus/pricing.md"}'),o={name:"el/plus/pricing.md"};function s(n,a,p,c,h,d){return i(),t("div",null,[...a[0]||(a[0]=[l('<h1 id="ελεγχος-τιμολογησης" tabindex="-1">Έλεγχος τιμολόγησης <a class="header-anchor" href="#ελεγχος-τιμολογησης" aria-label="Permalink to &quot;Έλεγχος τιμολόγησης&quot;">​</a></h1><div class="info custom-block"><p class="custom-block-title">Έκδοση αναφοράς</p><p>Πηγαίος κώδικας TransferBook+ v0.7.9. Το παρόν είναι τοπικό προσχέδιο προς έλεγχο, όχι επιβεβαίωση διαθεσιμότητας στην παραγωγή. Ελέγξτε την εγκατεστημένη έκδοση και τα δικαιώματά σας.</p></div><h2 id="εικονογραφημενη-προβολη" tabindex="-1">Εικονογραφημένη προβολή <a class="header-anchor" href="#εικονογραφημενη-προβολη" aria-label="Permalink to &quot;Εικονογραφημένη προβολή&quot;">​</a></h2><p><a href="/screenshots/v0.7.11/tariff-pricing.png"><img src="'+e+'" alt="Μηχανισμός τιμολόγησης: διαδρομές σταθερής τιμής, εποχικοί κανόνες, νυχτερινή προσαύξηση και κίνητρα επιστροφής. Οι τιμές είναι ενδεικτικές ρυθμίσεις δοκιμής, όχι εμπορικός τιμοκατάλογος."></a></p><p><em>Επιλέξτε την εικόνα για προβολή στο αρχικό της μέγεθος. Επιστρέψτε με το κουμπί Πίσω του προγράμματος περιήγησης.</em></p><p><em>Μηχανισμός τιμολόγησης: διαδρομές σταθερής τιμής, εποχικοί κανόνες, νυχτερινή προσαύξηση και κίνητρα επιστροφής. Οι τιμές είναι ενδεικτικές ρυθμίσεις δοκιμής, όχι εμπορικός τιμοκατάλογος.</em></p><p>Λήψη από περιβάλλον δοκιμών, TransferBook+ v0.7.11· αγγλικό περιβάλλον. Ενδεικτικά δοκιμαστικά στοιχεία. Η εικόνα δεν αποδεικνύει διαθεσιμότητα στην παραγωγή.</p><h2 id="σκοπος" tabindex="-1">Σκοπός <a class="header-anchor" href="#σκοπος" aria-label="Permalink to &quot;Σκοπός&quot;">​</a></h2><p>Ελέγξτε την τιμή πριν από επιβεβαίωση κράτησης. Ο κώδικας υποστηρίζει επαλήθευση προσφοράς από τον διακομιστή και υπολογισμούς σε ακέραια λεπτά του ευρώ.</p><h2 id="διαδικασια" tabindex="-1">Διαδικασία <a class="header-anchor" href="#διαδικασια" aria-label="Permalink to &quot;Διαδικασία&quot;">​</a></h2><ol><li>Επιβεβαιώστε διαδρομή, κατηγορία οχήματος, υπηρεσία και ημερομηνία/ώρα κάθε σκέλους.</li><li>Ελέγξτε τις ισχύουσες ρυθμισμένες χρεώσεις: τιμή διαδρομής, συντελεστή οχήματος, εποχική/νυχτερινή/εορταστική προσαύξηση, έκπτωση επιστροφής, πρόσθετα και φόρο.</li><li>Ελέγξτε την ανάλυση και το συνολικό ποσό σε EUR. Η επιστροφή μπορεί να έχει διαφορετικές προσαρμογές ανά σκέλος.</li><li>Περιμένετε νέα επαληθευμένη προσφορά αν τα τρέχοντα στοιχεία δεν έχουν ελεγχθεί. Μη χρησιμοποιείτε προηγούμενη τιμή.</li><li>Αν απαιτείται ειδική προσφορά, ακολουθήστε τις <a href="/el/plus/manual-quotations.html">χειροκίνητες προσφορές</a>.</li></ol><h2 id="αναμενομενο-αποτελεσμα-και-προβληματα" tabindex="-1">Αναμενόμενο αποτέλεσμα και προβλήματα <a class="header-anchor" href="#αναμενομενο-αποτελεσμα-και-προβληματα" aria-label="Permalink to &quot;Αναμενόμενο αποτέλεσμα και προβλήματα&quot;">​</a></h2><p>Η τιμή αντανακλά τις ρυθμίσεις και τα τρέχοντα στοιχεία κράτησης. Δεν επινοείται τιμή για μη ρυθμισμένη διαδρομή. Μηδενική προσωρινή ένδειξη δεν σημαίνει δωρεάν μεταφορά. Η εμφάνιση τιμής δεν αποδεικνύει είσπραξη.</p>',13)])])}const f=r(o,[["render",s]]);export{u as __pageData,f as default};
